export async function openOwnersList(page) {
    await page.getByRole("button", { name: "Owners" }).click();
    await page.getByRole("link", { name: "Search" }).click();
    await page.locator("#ownersTable table tbody > tr").first().waitFor({ state: "visible", timeout: 10000 });
}

export async function openOwnerDetail(page) {
    await page.locator("a[href=\"/petclinic/owners/1\"]").click();
}

export async function openOwnerEditForm(page) {
    await page.getByRole("button", { name: "Edit Owner" }).click();
    await page.getByRole("textbox", { name: "Phone" }).waitFor({ state: "visible", timeout: 10000 });
}

export async function openAddOwnerForm(page) {
    await page.getByRole("button", { name: "Owners" }).click();
    await page.getByRole("link", { name: "Add New" }).click();
    await page.locator("#phoneNumber").waitFor({ state: "visible", timeout: 10000 });
}

export async function fillOwnerForm(page, firstName, lastName, address, city, phoneNumber) {
    await page.locator("#firstName").fill(firstName);
    await page.locator("#lastName").fill(lastName);
    await page.locator("#address").fill(address);
    await page.locator("#city").fill(city);
    await page.locator("#phoneNumber").fill(phoneNumber);
    // Wait to finish any potential hydration
    await page.waitForTimeout(1500);
}

export async function submitAddOwnerForm(page) {
    await page.getByRole("button", { name: "Add Owner" }).click();
}
